import{_ as i}from"./chunks/29.DqY5OOFR.js";import{_ as n}from"./chunks/image3.z9AIU71X.js";import{_ as r}from"./chunks/image2.Dn1wLYA3.js";import{_ as s}from"./chunks/image1.DsLCzf1L.js";import{_ as l}from"./chunks/17.B2mNOKQ3.js";import{_ as d}from"./chunks/0.B7TrDeTt.js";import{_ as c}from"./chunks/1.BU1qyW7B.js";import{_ as t}from"./chunks/0.DyB7G7H5.js";import{_ as p}from"./chunks/3.PcdR27wg.js";import{_ as h}from"./chunks/5.BkY6Rw8O.js";import{_ as g}from"./chunks/0.C_OEUMPL.js";import{_ as m}from"./chunks/100.DMbJtyMU.js";import{_ as u}from"./chunks/community.BdKwbEUF.js";import{_ as b,C as _,o as f,c as y,ak as o,E as w}from"./chunks/framework.sbZkgmEx.js";const k="/projects/AiBlock/en/advanced-kit/assets/1.CUKiFq7z.webp",x="/projects/AiBlock/en/advanced-kit/assets/3.0fzcfFrp.webp",v="/projects/AiBlock/en/advanced-kit/assets/2.BGCB-lB2.webp",$=JSON.parse('{"title":"3.29 Seated Rowing Trainer","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.29 Seated Rowing Trainer.md","filePath":"docs/3.Creative Builds/3.29 Seated Rowing Trainer.md"}'),P={name:"docs/3.Creative Builds/3.29 Seated Rowing Trainer.md"};function q(T,e,z,S,A,C){const a=_("Pdf");return f(),y("div",null,[e[0]||(e[0]=o('<h1 id="_3-29-seated-rowing-trainer" tabindex="-1">3.29 Seated Rowing Trainer <a class="header-anchor" href="#_3-29-seated-rowing-trainer" aria-label="Permalink to &quot;3.29 Seated Rowing Trainer&quot;">​</a></h1><h2 id="_3-29-1-lesson-introduction" tabindex="-1">3.29.1 Lesson Introduction <a class="header-anchor" href="#_3-29-1-lesson-introduction" aria-label="Permalink to &quot;3.29.1 Lesson Introduction&quot;">​</a></h2><p>Centering on the smart seated rowing trainer model, this lesson explores coordinated programming across the 360° block motor, knob module, and dot matrix module. It implements an interactive fitness mechanism where knob rotation regulates reciprocating push-pull speeds while updating facial expressions on the dot matrix display. The content examines linkage transmission principles for reciprocating motion, covers single-motor push-pull mechanisms, and applies knob analog reading routines with display feedback to illustrate how interactive exercise machines integrate real-time state monitoring.</p><img loading="lazy" height="1662" width="1662" src="'+i+'" class="common_img" style="width:400px;"><h2 id="_3-29-2-learning-objectives" tabindex="-1">3.29.2 Learning Objectives <a class="header-anchor" href="#_3-29-2-learning-objectives" aria-label="Permalink to &quot;3.29.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Differentiate sequential, loop, and conditional branch structures in graphical programming. Master direction, braking, and speed control for the 360° block motor. Comprehend the analog readout logic of the knob module. Understand graphic calls on the dot matrix display alongside conditional evaluations of analog signals.</p></li><li><p><strong>Skill Objectives</strong>: Wire the 360° block motor, knob module, and dot matrix module properly. Assemble the mechanical structure of the Seated Rowing Trainer and calibrate mechanical travel limits. Program reciprocating motion loops combining knob speed regulation with dynamic expression transitions.</p></li><li><p><strong>Thinking Objectives</strong>: Build structured programming thinking through nested loop and conditional branch structures. Establish closed-loop control thinking linking knob input, logical evaluation, motor actuation, and display feedback. Cultivate engineering habits in knob range calibration, motor speed testing, and display parameter adjustment.</p></li><li><p><strong>Application Objectives</strong>: Explore operating principles behind knob-adjusted appliances, interactive gym equipment, and variable-speed toys. Independently expand advanced creative features such as multi-tiered speed regulation, animated expressions, and audiovisual notifications.</p></li></ol><h2 id="_3-29-3-preparation" tabindex="-1">3.29.3 Preparation <a class="header-anchor" href="#_3-29-3-preparation" aria-label="Permalink to &quot;3.29.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>Dot matrix module</p></li><li><p>Knob module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-29-4-hands-on-project" tabindex="-1">3.29.4 Hands-On Project <a class="header-anchor" href="#_3-29-4-hands-on-project" aria-label="Permalink to &quot;3.29.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Seated Rowing Trainer, delivering an interactive exercise machine where turning the knob regulates motor speed, showing a smiling face at zero speed and an exertion expression when running. The system adopts an input-logic-feedback architecture: the knob module serves as the speed regulation input, outputting an analog signal. In the decision stage, the program continuously samples the knob value and maps it to motor speed to govern machine operation. In the actuation stage, dual outputs operate in synchrony: a linkage mechanism driven by the 360° block motor pushes and pulls the handlebar for rowing exercise, while the dot matrix screen updates expressions corresponding to operational velocity. Both mechanical movement and display feedback operate in unison to provide clear visual feedback.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),w(a,{src:"../../_static/shared/pdf/chapter_3/29.pdf"}),e[1]||(e[1]=o('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the dot matrix module to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the knob module to port <strong>B</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1630" width="2300" src="'+k+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Knob</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;"><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+r+'" class="common_img" style="width:800px;"><ul><li>Select <strong>Dot matrix module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="90" width="677" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+d+'"></td><td style="text-align:left;">Reads the rotational position value of the potentiometer knob on the designated port across a range of 0 to 100, commonly used for parameter adjustment</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+t+'"></td><td style="text-align:left;">Directs the 360° block motor on the designated port to rotate continuously forward or in reverse at a custom speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+t+'"></td><td style="text-align:left;">Disables output to the 360° block motor on the designated port, halting rotation immediately</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="280" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+g+'"></td><td style="text-align:left;">Directs the dot matrix screen on the designated port to load and display preset graphic patterns</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="459" width="430" src="'+x+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><ul><li><p>Upon powering on, the program clears the dot matrix display on port A to finish initialization.</p></li><li><p>The main program then enters an infinite loop, continuously reading the analog value from the knob on port B and mapping it directly to the forward speed of motor S1 so that motor velocity dynamically follows knob rotation. The loop continuously evaluates whether the knob value equals 0: when the knob returns to zero, the dot matrix screen displays a smiling stop graphic. When the knob value is greater than 0, the screen switches to an exertion running graphic, pausing for 0.2 s at the end of each iteration to maintain program stability.</p></li></ul></li></ul><img loading="lazy" height="532" width="892" src="'+v+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+m+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1KQ-KBn3OmxCo6xKJkb7ZQZAuPW9brr5t?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-29-5-expansion-and-challenge" tabindex="-1">3.29.5 Expansion and Challenge <a class="header-anchor" href="#_3-29-5-expansion-and-challenge" aria-label="Permalink to &quot;3.29.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Multi-Tiered Speed Rowing Trainer</strong></p><p>Partition the knob range into discrete operating tiers where low knob angles command slow, gentle push-pull strokes, higher angles engage rapid reciprocating cycles, and the dot matrix display cycles through distinct facial expressions for each tier. Practice the full workflow uniting knob partitioning, speed switching, and expression mapping, exploring conditional branches and timing control while discussing gear selection in smart fitness machines.</p><p><strong>Project 2: Audiovisual Interactive Rowing Trainer</strong></p><p>Add a buzzer module: when turning the knob to initiate push-pull exercise at non-zero speeds, the buzzer plays an energetic rhythm, and when turning the knob back to zero, the motor stops and audio halts. Practice coordinating the dot matrix module, buzzer, and 360° block motor, mastering control architectures where a single knob signal directs multiple peripheral devices.</p><h2 id="_3-29-6-q-a" tabindex="-1">3.29.6 Q&amp;A <a class="header-anchor" href="#_3-29-6-q-a" aria-label="Permalink to &quot;3.29.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: What component regulates the push-pull speed of the trainer in this project, and how does it operate?</strong></p><p>Answer: The system uses a <strong>knob module</strong> to regulate push-pull speed. An internal potentiometer changes its analog voltage output in proportion to rotation angle: the controller reads this analog value and maps it to motor speed. Conditional statements in software partition the analog reading into distinct speed ranges or direct continuous mapping. Because the potentiometer is unaffected by ambient lighting, it is widely utilized across variable-speed gym equipment, dimmer switches, and interactive toys, allowing software parameter mapping to adapt easily to different control scenarios.</p><p><strong>Question 2: How does the software concurrently execute reciprocating push-pull mechanical motion and facial expression updates on the dot matrix screen?</strong></p><p>Answer: Synchronization occurs because <strong>the 360° block motor and the dot matrix module operate as two independent actuators</strong>, each functioning autonomously upon receiving instructions without interfering with the other. After reading the knob value and calculating motor speed, the program sets the motor to alternate between forward and reverse rotation, continuously driving the handlebar to push and pull. Simultaneously, the program issues graphic commands so the dot matrix screen updates its facial expression according to current velocity, delivering coordinated push-pull exercise alongside visual feedback. Note that the program executes sequentially: within the non-zero speed branch, the motor continuously alternates between forward and reverse rotation alongside delays while the dot matrix screen maintains the exertion graphic. When the knob returns to the zero-speed position, the program concurrently issues commands to halt the motor and switch back to the smiling expression. This reflects a key characteristic of multi-actuator systems, where each peripheral retains its active state and runs continuously without requiring the controller to retransmit repetitive instructions constantly.</p><h2 id="_3-29-7-technical-support-and-product-discussion" tabindex="-1">3.29.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-29-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.29.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+u+'" class="common_img" style="width:800px;"></a>',33))])}const L=b(P,[["render",q]]);export{$ as __pageData,L as default};
